-- Kalendrar. En användare kan skapa hur manya som helst, och varje
-- kalender har en egen färg. Händelser i en kalender ärver kalenderns
-- färg om de inte har en egen färg satt.
CREATE TABLE "calendars" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" INTEGER NOT NULL,
  "name" VARCHAR(64) NOT NULL,
  "color" VARCHAR(7) NOT NULL DEFAULT '#6366f1',
  "icon" VARCHAR(100),
  "is_default" BOOLEAN NOT NULL DEFAULT FALSE,
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE
);

CREATE INDEX "calendars_user_idx"
  ON "calendars" ("user_id", "sort_order", "id");

-- Endast en kalender per användare kan vara standardkalender.
CREATE UNIQUE INDEX "calendars_user_default_idx"
  ON "calendars" ("user_id")
  WHERE "is_default";

-- Calendar events. start_at is inclusive and end_at is exclusive.
CREATE TABLE "calendar_events" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" INTEGER NOT NULL,
  "goal_id" BIGINT,
  "calendar_id" BIGINT,
  "title" VARCHAR(255) NOT NULL,
  "description" TEXT,
  "icon" VARCHAR(100),
  "start_at" TIMESTAMPTZ NOT NULL,
  "end_at" TIMESTAMPTZ NOT NULL,
  "time_zone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
  "all_day" BOOLEAN NOT NULL DEFAULT FALSE,
  "status" VARCHAR(16) NOT NULL DEFAULT 'confirmed',
  "recurrence_rule" TEXT,
  "parent_event_id" BIGINT,
  "original_start_at" TIMESTAMPTZ,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT calendar_events_valid_time CHECK ("end_at" > "start_at"),
  CONSTRAINT calendar_events_valid_status CHECK ("status" IN ('confirmed', 'tentative', 'cancelled')),
  CONSTRAINT calendar_events_valid_recurrence_override CHECK (
    ("parent_event_id" IS NULL AND "original_start_at" IS NULL)
    OR ("parent_event_id" IS NOT NULL AND "original_start_at" IS NOT NULL)
  ),
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE,
  FOREIGN KEY ("goal_id") REFERENCES "goals"("id") ON DELETE SET NULL,
  FOREIGN KEY ("calendar_id") REFERENCES "calendars"("id") ON DELETE SET NULL,
  FOREIGN KEY ("parent_event_id") REFERENCES "calendar_events"("id") ON DELETE CASCADE
);

CREATE INDEX "calendar_events_user_start_idx"
  ON "calendar_events" ("user_id", "start_at");

CREATE INDEX "calendar_events_calendar_idx"
  ON "calendar_events" ("calendar_id");

CREATE UNIQUE INDEX "calendar_events_parent_original_start_idx"
  ON "calendar_events" ("parent_event_id", "original_start_at")
  WHERE "parent_event_id" IS NOT NULL;

-- Slutforda foreskomster for aterkommande mal. En rad per slutford
-- foreskomst, med vilken foreskomst det var och nar den slutfordes.
CREATE TABLE "goal_completions" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "goal_id" INTEGER NOT NULL,
  "occurrence_date" DATE NOT NULL,
  "completed_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT goal_completions_unique_occurrence UNIQUE ("goal_id", "occurrence_date"),
  FOREIGN KEY ("goal_id") REFERENCES "goals" ("id") ON DELETE CASCADE
);

CREATE INDEX "goal_completions_goal_idx"
  ON "goal_completions" ("goal_id");

-- API Keys for programmatic access (agents, integrations)
CREATE TABLE IF NOT EXISTS "api_keys" (
  "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
  "name" VARCHAR(100) NOT NULL,
  "key_hash" VARCHAR(255) NOT NULL UNIQUE,
  "user_id" INTEGER,
  "scope" VARCHAR(16) NOT NULL DEFAULT 'full',
  "created" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "last_used" TIMESTAMPTZ,
  "expires" TIMESTAMPTZ,
  PRIMARY KEY("id"),
  CONSTRAINT api_keys_valid_scope CHECK ("scope" IN ('full', 'agent')),
  FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE SET NULL
);

-- Agentkörningar: kopplingen mellan ett mål och det arbete en agent gör
-- med det. Plan äger tabellen, så gränssnittet visar agentens arbete även
-- när agent-tjänsten är nere.
CREATE TABLE IF NOT EXISTS "agent_runs" (
  "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
  "goal_id" INTEGER NOT NULL,
  "phase" VARCHAR(16) NOT NULL DEFAULT 'define',
  "status" VARCHAR(16) NOT NULL DEFAULT 'queued',
  "trigger" VARCHAR(16) NOT NULL DEFAULT 'user',
  "initiator" TEXT NOT NULL DEFAULT '',
  "agent_profile" VARCHAR(16) NOT NULL DEFAULT 'coding',
  "summary" TEXT,
  "result" TEXT NOT NULL DEFAULT '',
  "started_at" TIMESTAMPTZ,
  "finished_at" TIMESTAMPTZ,
  "artifact_url" TEXT,
  "cost_usd" DOUBLE PRECISION,
  "conversation_id" TEXT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY("id"),
  CONSTRAINT agent_runs_valid_phase CHECK ("phase" IN ('define', 'plan', 'execute', 'verify', 'completed')),
  CONSTRAINT agent_runs_valid_status CHECK ("status" IN ('queued', 'running', 'blocked', 'done', 'failed', 'cancelled')),
  CONSTRAINT agent_runs_valid_trigger CHECK ("trigger" IN ('user', 'schedule', 'webhook', 'agent')),
  CONSTRAINT agent_runs_valid_profile CHECK ("agent_profile" IN ('coding', 'life')),
  FOREIGN KEY ("goal_id") REFERENCES "goals"("id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "agent_runs_goal_idx"
  ON "agent_runs" ("goal_id");

-- Händelser ger Plan en kronologisk och strukturerad historik för varje körning.
CREATE TABLE IF NOT EXISTS "agent_run_events" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "agent_run_id" INTEGER NOT NULL,
  "type" VARCHAR(64) NOT NULL,
  "phase" VARCHAR(16) NOT NULL DEFAULT '',
  "payload" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  FOREIGN KEY ("agent_run_id") REFERENCES "agent_runs"("id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "agent_run_events_run_idx"
  ON "agent_run_events" ("agent_run_id", "created_at", "id");

-- Godkännanden: mänskliga beslut i agentkörningar. Plan äger dem, så
-- beslutet finns kvar även när agenttjänsten är nere.
CREATE TABLE IF NOT EXISTS "agent_approvals" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "agent_run_id" INTEGER NOT NULL,
  "goal_id" INTEGER NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "status" VARCHAR(16) NOT NULL DEFAULT 'pending',
  "decided_by" INTEGER,
  "feedback" TEXT NOT NULL DEFAULT '',
  "consequence" TEXT NOT NULL DEFAULT '',
  "verification_plan" TEXT NOT NULL DEFAULT '',
  "payload" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "decided_at" TIMESTAMPTZ,
  PRIMARY KEY ("id"),
  CONSTRAINT agent_approvals_valid_status CHECK ("status" IN ('pending', 'approved', 'rejected')),
  FOREIGN KEY ("agent_run_id") REFERENCES "agent_runs" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("goal_id") REFERENCES "goals" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("decided_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS "agent_approvals_run_idx"
  ON "agent_approvals" ("agent_run_id", "created_at", "id");

CREATE INDEX IF NOT EXISTS "agent_approvals_pending_idx"
  ON "agent_approvals" ("status") WHERE "status" = 'pending';
